sn_aia_tool.script:
(function(inputs) {

    var result = {
        total_tasks: 0,
        by_priority: {},
        by_state: {},
        by_assignment_group: {},
        by_use_case: {},
        by_problem_type: {},
        by_mess_hall: {},
        by_meal_type: {},
        by_approval: {},
        total_affected_students: 0
    };

    var gr = new GlideRecord('x_snc_campus_foo_1_complain_tasks');
    gr.query();

    while (gr.next()) {

        result.total_tasks++;

        var priority =
            gr.getDisplayValue('current_priority') ||
            'Not specified';

        var state =
            gr.getDisplayValue('state') ||
            'Not specified';

        var assignmentGroup =
            gr.getDisplayValue('assignment_group') ||
            'Not specified';

        var useCase =
            gr.getDisplayValue('use_case') ||
            'Not specified';

        var problemType =
            gr.getValue('problem_type') ||
            'Not specified';

        var messHall =
            gr.getDisplayValue('mess_hall') ||
            'Not specified';

        var mealType =
            gr.getDisplayValue('meal_type') ||
            'Not specified';

        var approval =
            gr.getDisplayValue('approval') ||
            'Not specified';

        var studentCount =
            parseInt(gr.getValue('student_count'), 10) || 0;

        result.total_affected_students += studentCount;


        if (!result.by_priority[priority])
            result.by_priority[priority] = 0;
        result.by_priority[priority]++;


        if (!result.by_state[state])
            result.by_state[state] = 0;
        result.by_state[state]++;


        if (!result.by_assignment_group[assignmentGroup])
            result.by_assignment_group[assignmentGroup] = 0;
        result.by_assignment_group[assignmentGroup]++;


        if (!result.by_use_case[useCase])
            result.by_use_case[useCase] = 0;
        result.by_use_case[useCase]++;


        if (!result.by_problem_type[problemType])
            result.by_problem_type[problemType] = 0;
        result.by_problem_type[problemType]++;


        if (!result.by_mess_hall[messHall])
            result.by_mess_hall[messHall] = 0;
        result.by_mess_hall[messHall]++;


        if (!result.by_meal_type[mealType])
            result.by_meal_type[mealType] = 0;
        result.by_meal_type[mealType]++;


        if (!result.by_approval[approval])
            result.by_approval[approval] = 0;
        result.by_approval[approval]++;
    }


    return {
        food_complaint_task_analytics: JSON.stringify(result)
    };

})(inputs);
